void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float d = length(uv);
    float speed = U.p0.x;
    float count = U.p0.y;
    float ring = 0.5 + 0.5 * sin(d * count - iTime * speed);
    ring = pow(ring, 6.0);
    vec3 dark = vec3(0.05, 0.02, 0.15);
    vec3 bright = vec3(0.2, 0.9, 1.0);
    vec3 col = mix(dark, bright, ring) * clamp(1.2 - d, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}
